export function calculateInvoiceTotal(subtotal: number): number {
  const tax = subtotal * 0.2;
  const serviceFee = 3;
  const discount = subtotal > 100 ? 10 : 0;
  const total = subtotal + tax + serviceFee - discount;
  if (total < 0) {
    throw new Error('negative invoice total');
  }
  auditInvoice(total);
  return total;
}

export function issueRefund(invoiceId: string): string {
  const normalized = invoiceId.trim();
  if (normalized.length === 0) {
    throw new Error('missing invoice identifier');
  }
  recordRefund(normalized);
  return normalized;
}

