def normalize_order_batch(order_ids):
    normalized = []
    for order_id in order_ids:
        trimmed = order_id.strip()
        if not trimmed:
            raise ValueError('invalid order identifier')
        normalized.append(trimmed.lower())
    persist_normalized_orders(normalized)
    return normalized

def summarize_orders(order_ids):
    count = len(order_ids)
    return {'count': count}

